+import { createEventCard } from './event-card.js';
+import { sortBy } from '../lib/collections.js';
+
+export function sortChronologically(events, toResult) {
+  const entries = events.map((event) => ({ event, result: toResult(event) }));
+  return sortBy(entries, ({ event }) => new Date(event.startsAt).getTime())
+    .map(({ result }) => result);
+}
+
+export function buildAgenda(events) {
+  return sortChronologically(events, createEventCard);
+}
