   return { items: items.slice(start, start + pageSize), total: items.length,
     page, pageSize, totalPages: Math.ceil(items.length / pageSize) };
 }
+
+export function sortBy(items, key) {
+  return items
+    .map((item, index) => ({ item, index, value: key(item) }))
+    .sort((a, b) => (a.value < b.value ? -1 : a.value > b.value ? 1 : a.index - b.index))
+    .map(({ item }) => item);
+}

